import sys

# Increase recursion depth just in case, though we use iterative BFS
sys.setrecursionlimit(2000000)

def solve():
    # Read all input at once
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T_str = next(iterator)
        T = int(T_str)
    except StopIteration:
        return

    MOD = 998244353

    for _ in range(T):
        try:
            H = int(next(iterator))
            W = int(next(iterator))
        except StopIteration:
            break

        grid = []
        for _ in range(H):
            grid.append(next(iterator))

        # Check row parities
        possible = True
        for r in range(H):
            row_str = grid[r]
            # Count 'A's
            cnt = 0
            for char in row_str:
                if char == 'A':
                    cnt += 1
            if cnt % 2 != 0:
                possible = False
                break

        if possible:
            # Check column parities
            for c in range(W):
                cnt = 0
                for r in range(H):
                    if grid[r][c] == 'A':
                        cnt += 1
                if cnt % 2 != 0:
                    possible = False
                    break

        if not possible:
            print(0)
            continue

        # Compute base solution X
        # X[r][c] is the value of the horizontal edge between col c and c+1 in row r
        # Constraint: x_{r, c-1} ^ x_{r, c} = r_val(r, c)
        # So x_{r, c} = x_{r, c-1} ^ r_val(r, c)
        # We fix X[r][0] = 0.
        X = [[0] * W for _ in range(H)]
        for r in range(H):
            curr = 0
            X[r][0] = 0
            for c in range(1, W):
                val = 1 if grid[r][c] == 'A' else 0
                curr = curr ^ val
                X[r][c] = curr
            # Consistency check with grid[r][0] is guaranteed by parity check

        # Compute base solution Y
        # Y[r][c] is the value of the vertical edge between row r and r+1 in col c
        # Constraint: y_{r-1, c} ^ y_{r, c} = r_val(r, c)
        # So y_{r, c} = y_{r-1, c} ^ r_val(r, c)
        # We fix Y[0][c] = 0.
        Y = [[0] * W for _ in range(H)]
        for c in range(W):
            curr = 0
            Y[0][c] = 0
            for r in range(1, H):
                val = 1 if grid[r][c] == 'A' else 0
                curr = curr ^ val
                Y[r][c] = curr
            # Consistency check with grid[0][c] is guaranteed by parity check

        # Build bipartite graph
        # Nodes 0..H-1 represent rows (variables u_i)
        # Nodes H..H+W-1 represent cols (variables v_j)
        adj = [[] for _ in range(H + W)]

        for r in range(H):
            for c in range(W):
                if grid[r][c] == 'B':
                    # Constraint: u_r ^ v_c = C_{r, c}
                    # C_{r, c} = 1 ^ Y_{r-1, c} ^ X_{r, c-1}
                    # Indices mod H, mod W

                    top_val = Y[(r - 1 + H) % H][c]
                    left_val = X[r][(c - 1 + W) % W]

                    C = 1 ^ top_val ^ left_val

                    u_node = r
                    v_node = H + c

                    adj[u_node].append((v_node, C))
                    adj[v_node].append((u_node, C))

        # BFS to check consistency and count connected components
        visited = [-1] * (H + W)
        components = 0
        consistent = True

        for i in range(H + W):
            if visited[i] == -1:
                components += 1
                # Start BFS
                queue = [i]
                visited[i] = 0
                idx = 0
                while idx < len(queue):
                    u = queue[idx]
                    idx += 1
                    val_u = visited[u]

                    for v, w in adj[u]:
                        expected = val_u ^ w
                        if visited[v] == -1:
                            visited[v] = expected
                            queue.append(v)
                        else:
                            if visited[v] != expected:
                                consistent = False
                                break
                    if not consistent:
                        break
                if not consistent:
                    break

        if not consistent:
            print(0)
        else:
            # Result 2^components
            ans = pow(2, components, MOD)
            print(ans)

if __name__ == '__main__':
    solve()

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        if abs(k) > 1800:
            return -1

        offset = 1800
        full_mask = (1 << 3601) - 1

        dp0 = [0] * (limit + 1)
        dp1 = [0] * (limit + 1)

        for x in nums:
            new_dp0 = dp0[:]
            new_dp1 = dp1[:]
            for p in range(limit, -1, -1):
                if dp0[p]:
                    np = p * x
                    if np <= limit:
                        new_dp1[np] |= (dp0[p] << x) & full_mask
                if dp1[p]:
                    np = p * x
                    if np <= limit:
                        new_dp0[np] |= (dp1[p] >> x) & full_mask
            if x <= limit:
                new_dp1[x] |= (1 << (x + offset)) & full_mask
            dp0, dp1 = new_dp0, new_dp1

        for p in range(limit, -1, -1):
            if (dp0[p] >> (k + offset)) & 1 or (dp1[p] >> (k + offset)) & 1:
                return p
        return -1

import sys

def solve():
    # Read all input at once
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    s = input_data[1]
    t = input_data[2]

    # Map from char index (0-25) to target char index
    # -1 means not present in S
    m = [-1] * 26

    # Check consistency and build map
    for i in range(n):
        u = ord(s[i]) - 97
        v = ord(t[i]) - 97

        if m[u] != -1:
            if m[u] != v:
                print("-1")
                return
        else:
            m[u] = v

    # Count unique characters in S
    unique_chars = len(set(s))

    # Count K: number of characters that need to change
    k = 0
    for u in range(26):
        if m[u] != -1 and m[u] != u:
            k += 1

    # Count cycles of length > 1
    c = 0
    visited = [0] * 26 # 0: unvisited, 1: visiting, 2: visited

    for u in range(26):
        if m[u] == -1 or visited[u] == 2:
            continue

        path = []
        curr = u
        while True:
            if m[curr] == -1:
                break
            if visited[curr] == 1:
                # Cycle detected
                # curr is the node where cycle closes
                try:
                    idx = path.index(curr)
                    cycle_len = len(path) - idx
                    if cycle_len > 1:
                        c += 1
                except ValueError:
                    pass
                break
            if visited[curr] == 2:
                break

            visited[curr] = 1
            path.append(curr)
            curr = m[curr]

        for node in path:
            visited[node] = 2

    # If there are cycles of length > 1, we need a temporary character.
    # If S contains all 26 characters, we cannot find a temporary character.
    if c > 0 and unique_chars == 26:
        print("-1")
    else:
        print(k + c)

if __name__ == '__main__':
    solve()

from functools import lru_cache

class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count_upto(n, s):
            if n <= 0: 
                return 0
            digits = list(map(int, str(n)))
            m = len(digits)

            @lru_cache(None)
            def dp(idx, cur_sum, cur_prod_mod, tight, leading_zeros):
                # Pruning: sum already exceeds target
                if cur_sum > s:
                    return 0
                # Pruning: cannot reach target sum even with all 9s
                if cur_sum + (m - idx) * 9 < s:
                    return 0
                # Base case: reached end of digits
                if idx == m:
                    return 1 if cur_sum == s and cur_prod_mod == 0 else 0

                limit = digits[idx] if tight else 9
                res = 0
                for d in range(limit + 1):
                    new_tight = tight and (d == limit)
                    new_leading_zeros = leading_zeros and (d == 0)
                    new_sum = cur_sum + d

                    if new_sum > s:
                        continue

                    if new_leading_zeros:
                        new_prod_mod = 1
                    else:
                        if cur_prod_mod == 0 or d == 0:
                            new_prod_mod = 0
                        else:
                            new_prod_mod = (cur_prod_mod * d) % s

                    res += dp(idx + 1, new_sum, new_prod_mod, new_tight, new_leading_zeros)
                return res

            return dp(0, 0, 1, True, True)

        ans = 0
        # Iterate over all possible digit sums (max sum for numbers < 10^9 is 81)
        for s in range(1, 82):
            ans += count_upto(r, s) - count_upto(l - 1, s)
        return ans

class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        if n < k:
            return [0] * n

        from collections import defaultdict
        cnt = defaultdict(int)

        # Count frequency of every prefix
        for w in words:
            for l in range(1, len(w) + 1):
                cnt[w[:l]] += 1

        M = 0
        Q = []
        for p, c in cnt.items():
            if c >= k + 1:
                M = max(M, len(p))
            elif c == k:
                Q.append(p)

        # Build Trie for Q, storing max_len in each node
        trie = {}
        for p in Q:
            node = trie
            for ch in p:
                if ch not in node:
                    node[ch] = {}
                node = node[ch]
                node['max_len'] = max(node.get('max_len', 0), len(p))

        ans = []
        for w in words:
            node = trie
            res = 0
            # Initially, all prefixes in Q are candidates
            res = max(res, trie.get('max_len', 0))

            # Traverse the Trie with w to find the longest prefix in Q that is NOT a prefix of w
            for ch in w:
                if ch in node:
                    node = node[ch]
                    res = max(res, node.get('max_len', 0))
                else:
                    # Cannot continue, all remaining prefixes in Q are valid candidates
                    res = max(res, node.get('max_len', 0))
                    break

            ans.append(max(M, res))

        return ans

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        L = n + m - 1
        word = [None] * L

        # Apply T constraints
        for i, ch in enumerate(str1):
            if ch == 'T':
                for k in range(m):
                    idx = i + k
                    if word[idx] is not None and word[idx] != str2[k]:
                        return ""
                    word[idx] = str2[k]

        # Compute initial free_count and critical
        free_count = [0] * n
        critical = set()
        for i in range(n):
            if str1[i] == 'F':
                cnt = 0
                for k in range(m):
                    idx = i + k
                    if word[idx] is None or word[idx] != str2[k]:
                        cnt += 1
                free_count[i] = cnt
                if cnt == 0:
                    return ""
                if cnt == 1:
                    critical.add(i)

        path = []
        j = 0
        while j < L:
            if word[j] is not None:
                j += 1
                continue

            found = False
            for c in "abcdefghijklmnopqrstuvwxyz":
                word[j] = c
                valid = True
                affected = []

                start_i = max(0, j - m + 1)
                end_i = min(j, n - 1)
                for i in range(start_i, end_i + 1):
                    if str1[i] == 'F':
                        old_val = free_count[i]
                        # word[j] was None, contributed 1.
                        # new contribution: 0 if c == str2[j-i] else 1.
                        delta = (0 if c == str2[j-i] else 1) - 1
                        free_count[i] += delta
                        if free_count[i] == 0:
                            valid = False
                            # Revert free_count changes
                            for ii, ov in affected:
                                free_count[ii] = ov
                            break
                        affected.append((i, old_val))

                if valid:
                    # Commit changes to critical set
                    for i, old_val in affected:
                        if free_count[i] == 1:
                            critical.add(i)
                        elif free_count[i] > 1 and i in critical:
                            critical.remove(i)
                    path.append((j, c, affected))
                    j += 1
                    found = True
                    break

            if not found:
                if not path:
                    return ""
                prev_j, prev_c, affected = path.pop()
                word[prev_j] = None
                for i, old_val in affected:
                    free_count[i] = old_val
                    if old_val == 1:
                        critical.add(i)
                    elif old_val > 1 and i in critical:
                        critical.remove(i)
                j = prev_j

        return "".join(word)

from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        max_odd = (n + 1) // 2
        max_even = n // 2

        # dp[o][e][p] stores the number of alternating permutations of length o+e
        # using o odd numbers and e even numbers, starting with parity p (0 for even, 1 for odd)
        dp = [[[0] * 2 for _ in range(max_even + 1)] for _ in range(max_odd + 1)]
        dp[0][0][0] = 1
        dp[0][0][1] = 1

        for o in range(max_odd + 1):
            for e in range(max_even + 1):
                if o == 0 and e == 0:
                    continue

                if o > 0:
                    dp[o][e][1] = o * dp[o-1][e][0]
                    if dp[o][e][1] > 10**16:
                        dp[o][e][1] = 10**16

                if e > 0:
                    dp[o][e][0] = e * dp[o][e-1][1]
                    if dp[o][e][0] > 10**16:
                        dp[o][e][0] = 10**16

        used = [False] * (n + 1)
        rem_odd = max_odd
        rem_even = max_even
        result = []

        for i in range(n):
            found = False
            for num in range(1, n + 1):
                if used[num]:
                    continue

                if i > 0:
                    if (num % 2) == (result[-1] % 2):
                        continue

                parity_num = num % 2
                next_parity = 1 - parity_num

                r_odd = rem_odd - (1 if parity_num == 1 else 0)
                r_even = rem_even - (1 if parity_num == 0 else 0)

                count = dp[r_odd][r_even][next_parity]

                if k <= count:
                    result.append(num)
                    used[num] = True
                    rem_odd = r_odd
                    rem_even = r_even
                    found = True
                    break
                else:
                    k -= count

            if not found:
                return []

        return result

import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    N = int(input_data[0])
    s = input_data[1]

    MOD = 998244353

    # State mapping:
    # 0: (0, None)
    # 1: (1, Up)
    # 2: (0, Up)
    # 3: (-1, Down)
    # 4: (0, Down)

    transitions = [[[] for _ in range(6)] for _ in range(5)]

    def get_state(P, mode):
        if mode == 0: return 0
        elif mode == 1:
            if P == 1: return 1
            elif P == 0: return 2
        elif mode == 2:
            if P == -1: return 3
            elif P == 0: return 4
        return -1

    def get_next_state(current_state, delta):
        if current_state == 0: P, mode = 0, 0
        elif current_state == 1: P, mode = 1, 1
        elif current_state == 2: P, mode = 0, 1
        elif current_state == 3: P, mode = -1, 2
        elif current_state == 4: P, mode = 0, 2

        P_new = P + delta

        if mode == 0:
            if P_new == 1: new_mode = 1
            elif P_new == -1: new_mode = 2
            elif P_new == 0: new_mode = 0
            else: return -1
        elif mode == 1:
            if P_new in [0, 1]: new_mode = 1
            else: return -1
        elif mode == 2:
            if P_new in [-1, 0]: new_mode = 2
            else: return -1

        return get_state(P_new, new_mode)

    for s_idx in range(5):
        for u in range(-1, 3):
            # Try delta = u
            next_s = get_next_state(s_idx, u)
            if next_s != -1:
                transitions[s_idx][u+3].append(next_s)
            # Try delta = u-1
            next_s = get_next_state(s_idx, u-1)
            if next_s != -1:
                transitions[s_idx][u+3].append(next_s)

    next_masks = [[0]*6 for _ in range(32)]
    for mask in range(32):
        for u in range(-1, 3):
            nm = 0
            for s_idx in range(5):
                if (mask >> s_idx) & 1:
                    for ns in transitions[s_idx][u+3]:
                        nm |= (1 << ns)
            next_masks[mask][u+3] = nm

    dp = [0] * 32
    dp[1] = 1

    for k in range(N):
        new_dp = [0] * 32
        s_k = s[k]

        if s_k == '0':
            valid_u = [2, 3, 4] 
        else:
            valid_u = [2, 3, 4, 5] 

        for mask in range(32):
            if dp[mask] == 0:
                continue
            val = dp[mask]
            for u_idx in valid_u:
                new_dp[next_masks[mask][u_idx]] = (new_dp[next_masks[mask][u_idx]] + val) % MOD

        dp = new_dp

    ans = 0
    for mask in range(32):
        if (mask & 1) or (mask & 4) or (mask & 16):
            ans = (ans + dp[mask]) % MOD

    print(ans)

solve()

import bisect
from typing import List

class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        def get_perimeter_coord(point):
            x, y = point
            if y == 0:
                return x
            elif x == side:
                return side + y
            elif y == side:
                return 2 * side + (side - x)
            elif x == 0:
                return 3 * side + (side - y)

        points_1d = sorted([get_perimeter_coord(p) for p in points])
        n = len(points_1d)
        perimeter = 4 * side
        extended = points_1d + [p + perimeter for p in points_1d]

        def can_select_k(D):
            for i in range(n):
                count = 1
                last = points_1d[i]
                idx = bisect.bisect_left(extended, last + D, i + 1)
                while count < k and idx < i + n:
                    count += 1
                    last = extended[idx]
                    idx = bisect.bisect_left(extended, last + D, idx + 1)

                if count == k:
                    if extended[i + n] - last >= D:
                        return True
            return False

        low, high = 0, perimeter
        ans = 0
        while low <= high:
            mid = (low + high) // 2
            if can_select_k(mid):
                ans = mid
                low = mid + 1
            else:
                high = mid - 1
        return ans

import sys

def solve():
    # Read all input from stdin efficiently
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        N = int(next(iterator))
    except StopIteration:
        return

    if N == 1:
        print(-1)
        return

    adj = [[] for _ in range(N + 1)]
    for _ in range(N - 1):
        u = int(next(iterator))
        v = int(next(iterator))
        adj[u].append(v)
        adj[v].append(u)

    INF_NEG = -10**9
    # Fixed: Changed -INF_NEG to INF_NEG for proper negative infinity initialization
    dp = [[[INF_NEG] * 2 for _ in range(5)] for _ in range(N + 1)]

    ans = INF_NEG

    # Iterative DFS to determine processing order (bottom-up)
    parent = [0] * (N + 1)
    order = []
    stack = [1]
    visited = [False] * (N + 1)
    visited[1] = True

    while stack:
        u = stack.pop()
        order.append(u)
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                parent[v] = u
                stack.append(v)

    # Process in reverse order (bottom-up)
    for u in reversed(order):
        # cur[c][h] stores the max size of the forest of children subtrees
        # with exactly c children chosen and h indicating if there is a deg4 vertex
        cur = [[INF_NEG] * 2 for _ in range(5)]
        cur[0][0] = 0

        for v in adj[u]:
            if v == parent[u]:
                continue

            # Compute best[dc][dh] for child v
            # dc in 0..1, dh in 0..1
            best = [[INF_NEG] * 2 for _ in range(2)]
            best[0][0] = 0  # Option to skip v

            # Option: Take v with 0 children in alkane -> v has degree 1 in alkane
            if dp[v][0][0] > INF_NEG // 2:
                best[1][0] = max(best[1][0], dp[v][0][0])
            if dp[v][0][1] > INF_NEG // 2:
                best[1][1] = max(best[1][1], dp[v][0][1])

            # Option: Take v with 3 children in alkane -> v has degree 4 in alkane
            # v becomes a degree-4 vertex, so h must be 1
            if dp[v][3][0] > INF_NEG // 2:
                best[1][1] = max(best[1][1], dp[v][3][0])
            if dp[v][3][1] > INF_NEG // 2:
                best[1][1] = max(best[1][1], dp[v][3][1])

            # Knapsack-like DP to combine children
            next_cur = [[INF_NEG] * 2 for _ in range(5)]
            for c in range(5):
                for h in range(2):
                    if cur[c][h] <= INF_NEG // 2:
                        continue
                    for dc in range(2):
                        for dh in range(2):
                            if best[dc][dh] <= INF_NEG // 2:
                                continue
                            new_c = c + dc
                            if new_c > 4:
                                continue
                            new_h = h | dh
                            new_size = cur[c][h] + best[dc][dh]
                            if new_size > next_cur[new_c][new_h]:
                                next_cur[new_c][new_h] = new_size
            cur = next_cur

        # Compute dp[u][c][h]
        for c in range(5):
            for h in range(2):
                if cur[c][h] > INF_NEG // 2:
                    dp[u][c][h] = 1 + cur[c][h]

        # Update global answer
        # The alkane can be rooted at u.
        # If rooted at u, u must have 1 or 4 children in alkane.
        # If c=1, u has degree 1, so we need a deg4 vertex in children. So h=1.
        # If c=4, u has degree 4, so u is deg4. So h can be 0 or 1.
        if dp[u][1][1] > ans:
            ans = dp[u][1][1]
        if dp[u][4][0] > ans:
            ans = dp[u][4][0]
        if dp[u][4][1] > ans:
            ans = dp[u][4][1]

    if ans <= INF_NEG // 2:
        print(-1)
    else:
        print(ans)

solve()

import sys
import heapq

def solve():
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    C = data[1:N+1]

    # Precompute adjacency lists
    # In[x][c] = list of u such that u -> x with label c
    # Out[y][c] = list of v such that y -> v with label c
    In = [[[] for _ in range(26)] for _ in range(N)]
    Out = [[[] for _ in range(26)] for _ in range(N)]

    for i in range(N):
        for j in range(N):
            c = C[i][j]
            if c != '-':
                idx = ord(c) - ord('a')
                Out[i][idx].append(j)
                In[j][idx].append(i)

    # Distance matrix
    INF = float('inf')
    dist = [[INF] * N for _ in range(N)]

    pq = []

    # Base cases: dist[u][u] = 0
    for u in range(N):
        dist[u][u] = 0
        heapq.heappush(pq, (0, u, u))

    # Base cases: dist[u][v] = 1 if edge u -> v exists
    for i in range(N):
        for j in range(N):
            c = C[i][j]
            if c != '-':
                if dist[i][j] > 1:
                    dist[i][j] = 1
                    heapq.heappush(pq, (1, i, j))

    # Dijkstra
    while pq:
        d, x, y = heapq.heappop(pq)

        if d > dist[x][y]:
            continue

        # Try to extend with matching labels
        for c in range(26):
            U = In[x][c]
            V = Out[y][c]

            if not U or not V:
                continue

            new_d = d + 2
            for u in U:
                for v in V:
                    if new_d < dist[u][v]:
                        dist[u][v] = new_d
                        heapq.heappush(pq, (new_d, u, v))

    # Output
    for i in range(N):
        print(' '.join(str(dist[i][j]) if dist[i][j] != INF else '-1' for j in range(N)))

solve()

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])

        # Directions: 0=DR(1,1), 1=DL(1,-1), 2=UL(-1,-1), 3=UR(-1,1)
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]

