        # state: 0=expecting 1 (start), 1=expecting 2, 2=expecting 0
        dp_in = [[[0] * m for _ in range(n)] for _ in range(4)]
        dp_out = [[[0] * m for _ in range(n)] for _ in range(4)]

        max_len = 0

        # Fill dp_in for each direction (process in direction of movement)
        for d in range(4):
            di, dj = dirs[d]
