                for i in range(n):
                    for j in range(m):
                        if grid[i][j] == 1:
                            dp_in[d][0][i][j] = 1
                        elif grid[i][j] == 2:
                            pi, pj = i - di, j - dj
                            if 0 <= pi < n and 0 <= pj < m:
                                dp_in[d][1][i][j] = max(dp_in[d][0][pi][pj], dp_in[d][2][pi][pj]) + 1
                        elif grid[i][j] == 0:
                            pi, pj = i - di, j - dj
                            if 0 <= pi < n and 0 <= pj < m:
                                dp_in[d][2][i][j] = dp_in[d][1][pi][pj] + 1
            elif d == 1:  # DL: i from 0..n-1, j from m-1..0
