                            if 0 <= ni < n and 0 <= nj < m:
                                dp_out[d][1][i][j] = max(dp_out[d][0][ni][nj], dp_out[d][2][ni][nj]) + 1
                        elif grid[i][j] == 0:
                            ni, nj = i + di, j + dj
                            if 0 <= ni < n and 0 <= nj < m:
                                dp_out[d][2][i][j] = dp_out[d][1][ni][nj] + 1
            elif d == 1:  # DL: i from n-1..0, j from 0..m-1
                for i in range(n - 1, -1, -1):
                    for j in range(m):
