            elif d == 2:  # UL: i from 0..n-1, j from 0..m-1
                for i in range(n):
                    for j in range(m):
                        if grid[i][j] == 1:
                            dp_out[d][0][i][j] = 1
                        elif grid[i][j] == 2:
