                        elif grid[i][j] == 0:
                            ni, nj = i + di, j + dj
                            if 0 <= ni < n and 0 <= nj < m:
                                dp_out[d][2][i][j] = dp_out[d][1][ni][nj] + 1
            elif d == 3:  # UR: i from 0..n-1, j from m-1..0
                for i in range(n):
                    for j in range(m - 1, -1, -1):
                        if grid[i][j] == 1:
                            dp_out[d][0][i][j] = 1
                        elif grid[i][j] == 2:
                            ni, nj = i + di, j + dj
                            if 0 <= ni < n and 0 <= nj < m:
                                dp_out[d][1][i][j] = max(dp_out[d][0][ni][nj], dp_out[d][2][ni][nj]) + 1
                        elif grid[i][j] == 0:
                            ni, nj = i + di, j + dj
                            if 0 <= ni < n and 0 <= nj < m:
                                dp_out[d][2][i][j] = dp_out[d][1][ni][nj] + 1

        # Combine dp_in and dp_out: straight segments + V-shapes with clockwise turn
        for i in range(n):
            for j in range(m):
                for d in range(4):
                    # Straight segment (at most 0 turns)
                    for s in range(3):
                        if dp_in[d][s][i][j] > max_len:
                            max_len = dp_in[d][s][i][j]

                    # V-shape: incoming direction d, outgoing direction (d+1)%4 (clockwise turn)
                    od = (d + 1) % 4
                    for s in range(3):
                        if dp_in[d][s][i][j] > 0 and dp_out[od][s][i][j] > 0:
                            total = dp_in[d][s][i][j] + dp_out[od][s][i][j] - 1
                            if total > max_len:
                                max_len = total

        return max_len

