    freq = [0] * (M + 1)
    for x in A:
        freq[x] += 1

    # Compute C[g]: number of elements in A that are multiples of g
    # Using slice summation for speed
    C = [0] * (M + 1)
    for g in range(1, M + 1):
        C[g] = sum(freq[g::g])

    ans = [0] * (M + 1)

    # Iterate g from largest to smallest
    for g in range(M, 0, -1):
        if C[g] >= K:
            # Assign ans[x] = g for all multiples x of g that are not yet assigned
            x = g
            while x <= M:
                if ans[x] == 0:
                    ans[x] = g
                x += g

    # Collect results
    out = []
    for x in A:
        out.append(str(ans[x]))
    sys.stdout.write('\n'.join(out) + '\n')

