import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        N = int(next(iterator))
        A = []
        for _ in range(N-1):
            A.append(int(next(iterator)))
    except StopIteration:
        return

    MOD = 998244353

    MAX_A = 1000
    primes = []
    is_prime = [True] * (MAX_A + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, MAX_A + 1):
        if is_prime[i]:
            primes.append(i)
            for j in range(i*i, MAX_A + 1, i):
                is_prime[j] = False

    total_ans = 1

    for p in primes:
        alphas = []
        for val in A:
            cnt = 0
            while val % p == 0:
                cnt += 1
                val //= p
            alphas.append(cnt)

        if all(a == 0 for a in alphas):
            continue

        # dp state: (d, md, me, last_x) -> weight
        dp = {}
        # Initial state for i=1
        # D_1 = 0, md_1 = 0, me_1 = E_1 = x_1 * alpha_1
        # last_x = x_1
        dp[(0, 0, 0, 0)] = 1
        dp[(0, 0, alphas[0], 1)] = pow(p, alphas[0], MOD)

        # Loop from i=1 to N-2
        # At start of loop i, we have states for i
        # We compute states for i+1
        for i in range(1, N-1):
            new_dp = {}
            alpha_i = alphas[i-1] # alpha_i in 1-indexed is alphas[i-1] in 0-indexed
            # E_{i+1} = (1 - x_i) * alpha_i
            # D_{i+1} = D_i + E_{i+1} - x_{i+1} * alpha_{i+1}
            # alpha_{i+1} is alphas[i]

            alpha_next = alphas[i]

            for (d, md, me, last_x), weight in dp.items():
                # last_x is x_i
                E_next = (1 - last_x) * alpha_i

                # We need to iterate over x_{i+1}
                for x_next in [0, 1]:
                    D_next = d + E_next - x_next * alpha_next
                    md_next = min(md, D_next)
                    me_next = min(me, E_next)

                    if md_next >= me_next:
                        new_weight = (weight * pow(p, E_next, MOD)) % MOD
                        key = (D_next, md_next, me_next, x_next)
                        new_dp[key] = (new_dp.get(key, 0) + new_weight) % MOD

            dp = new_dp
            if not dp:
                break

        # Final step for i = N-1 to N
        # We have states for i = N-1
        # Compute E_N and D_N
        alpha_last = alphas[N-2] # alpha_{N-1}

        prime_ans = 0
        for (d, md, me, last_x), weight in dp.items():
            E_N = (1 - last_x) * alpha_last
            D_N = d + E_N
            md_N = min(md, D_N)
            me_N = min(me, E_N)

            if md_N >= me_N:
                # Weight includes p^{sum_{j=1}^{N-1} E_j}
                # We need to multiply by p^{E_N}
                new_weight = (weight * pow(p, E_N, MOD)) % MOD

                # Term is p^{N * (-me_N) + sum_{j=1}^N E_j}
                # = new_weight * p^{-N * me_N}

                # Compute p^{-N * me_N}
                exp = N * me_N
                if exp == 0:
                    inv_val = 1
                else:
                    val = pow(p, abs(exp), MOD)
                    inv_val = pow(val, MOD-2, MOD)

                term = (new_weight * inv_val) % MOD
                prime_ans = (prime_ans + term) % MOD

        total_ans = (total_ans * prime_ans) % MOD

    print(total_ans)

solve()

class Solution:
    def countSubstrings(self, s: str) -> int:
        # Precompute powers of 10 modulo d for d in 1..9
        pow10 = [[0]*6 for _ in range(10)]
        for d in range(1, 10):
            for k in range(6):
                pow10[d][k] = pow(10, k, d)

        # Precompute valid remainders r for each d, val, target such that r * val == target (mod d)
        solutions = [[ [ [] for _ in range(9) ] for _ in range(10) ] for _ in range(10)]
        for d in range(1, 10):
            for val in range(d):
                for target in range(d):
                    for r in range(d):
                        if (r * val) % d == target:
                            solutions[d][val][target].append(r)

        # cnt[d][rem][i_mod] stores count of prefix indices i such that P_i % d == rem and i % 6 == i_mod
        cnt = [[ [0]*6 for _ in range(9) ] for _ in range(10)]
        for d in range(1, 10):
            cnt[d][0][0] = 1  # Base case: P_0 = 0 at index 0

        P = 0
        ans = 0
        for j, ch in enumerate(s):
            d = int(ch)
            P = (P * 10 + d) % 2520  # LCM(1..9) = 2520

            if d != 0:
                for dd in range(1, 10):
                    target = P % dd
                    for i_mod in range(6):
                        len_mod = (j + 1 - i_mod) % 6
                        val = pow10[dd][len_mod]
                        for r in solutions[dd][val][target]:
                            ans += cnt[dd][r][i_mod]

            for dd in range(1, 10):
                cnt[dd][P % dd][(j+1) % 6] += 1

        return ans

class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)
        low, high = 0, m * max(points) + 1

        def check(X):
            # Calculate minimum visits required for each index to achieve score X
            c = [(X + p - 1) // p for p in points]
            v = [0] * n
            v[0] = c[0]

            # Forward pass: enforce v[i] >= v[i-1] - 1
            for i in range(1, n):
                v[i] = max(c[i], v[i-1] - 1)

            # Backward pass: enforce v[i] >= v[i+1] - 1
            for i in range(n-2, -1, -1):
                v[i] = max(v[i], v[i+1] - 1)

            return sum(v) <= m

        while low < high:
            mid = (low + high + 1) // 2
            if check(mid):
                low = mid
            else:
                high = mid - 1
        return low

