    solve()

class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)

        def count_pairs(left, right, k):
            S = k + 1
            a_max = min(left, S - 1)
            if a_max <= 0:
                return 0
            a_split = S - right
            if a_split >= a_max:
                return a_max * right
            elif a_split < 1:
                return a_max * S - a_max * (a_max + 1) // 2
            else:
                part1 = a_split * right
                part2 = (a_max - a_split) * S - (a_max * (a_max + 1) // 2 - a_split * (a_split + 1) // 2)
                return part1 + part2

        def get_boundaries(nums, is_max):
            L = [-1] * n
            R = [n] * n
            stack = []

            for i in range(n):
                if is_max:
                    while stack and nums[stack[-1]] < nums[i]:
                        stack.pop()
                else:
                    while stack and nums[stack[-1]] > nums[i]:
                        stack.pop()
                L[i] = stack[-1] if stack else -1
                stack.append(i)

            stack = []
            for i in range(n - 1, -1, -1):
                if is_max:
                    while stack and nums[stack[-1]] <= nums[i]:
                        stack.pop()
                else:
                    while stack and nums[stack[-1]] >= nums[i]:
                        stack.pop()
                R[i] = stack[-1] if stack else n
                stack.append(i)

            return L, R

        total_sum = 0

        L_max, R_max = get_boundaries(nums, True)
        for i in range(n):
            left = i - L_max[i]
            right = R_max[i] - i
            total_sum += nums[i] * count_pairs(left, right, k)

        L_min, R_min = get_boundaries(nums, False)
        for i in range(n):
            left = i - L_min[i]
            right = R_min[i] - i
            total_sum += nums[i] * count_pairs(left, right, k)

        return total_sum

import sys

def solve():
    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx]); idx += 1
    p = int(input[idx]); idx += 1

    A = []
    for i in range(N):
        row = []
        for j in range(N):
            row.append(int(input[idx])); idx += 1
        A.append(row)

    if p == 2:
        # B is all 1s, B^2 has all entries equal to N
        for i in range(N):
            print(' '.join([str(N % 2)] * N))
        return

    # Compute M^p mod p where M has 0 where A has 0
    M = [row[:] for row in A]
    for i in range(N):
        for j in range(N):
            if M[i][j] == 0:
                M[i][j] = 0  # already 0

    # Matrix multiplication mod p
    def mat_mul(X, Y):
        Z = [[0] * N for _ in range(N)]
        for i in range(N):
            for k in range(N):
                if X[i][k] == 0:
                    continue
                for j in range(N):
                    Z[i][j] = (Z[i][j] + X[i][k] * Y[k][j]) % p
        return Z

    def mat_pow(X, exp):
        result = [[0] * N for _ in range(N)]
        for i in range(N):
            result[i][i] = 1
        base = [row[:] for row in X]
        while exp > 0:
            if exp % 2 == 1:
                result = mat_mul(result, base)
            base = mat_mul(base, base)
            exp //= 2
        return result

    S = mat_pow(M, p)

    # Count zeros
    Z_count = 0
    for i in range(N):
        for j in range(N):
            if A[i][j] == 0:
                Z_count += 1

    # Add contributions from zero edges
    for i in range(N):
        for j in range(N):
            if A[i][j] == 0:
                if i == j:
                    # Zero self-loop
                    for k in range(N):
                        if A[i][k] != 0:
                            S[i][k] = (S[i][k] + A[i][k]) % p
                else:
                    # Zero edge (i,j) with i != j
                    if p == 3 and A[j][i] != 0:
                        S[i][j] = (S[i][j] + A[j][i]) % p

    # Multiply by (-1)^Z_count
    if Z_count % 2 == 1:
        for i in range(N):
            for j in range(N):
                S[i][j] = (-S[i][j]) % p

    # Print result
    for i in range(N):
        print(' '.join([str(S[i][j]) for j in range(N)]))

solve()

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        st = []
        current_cost = 0
        left = 0
        ans = 0
        P = [0] * (n + 1)
        for i in range(n):
            P[i+1] = P[i] + nums[i]

        for right in range(n):
            while st and nums[st[-1]] <= nums[right]:
                p = st.pop()
                prev = st[-1] if st else left
                current_cost += (nums[right] - nums[p]) * (p - prev)
            st.append(right)
            if st:
                current_cost += nums[st[-1]] - nums[right]

            while current_cost > k:
                if st[0] == left:
                    next_peak = st[1] if len(st) > 1 else right + 1
                    current_cost -= nums[left] * (next_peak - left - 1) - (P[next_peak] - P[left+1])
                    st.pop(0)
                else:
                    current_cost -= nums[left+1]
                left += 1

            ans += right - left + 1

        return ans

import sys

def solve():
    # Read all input from stdin efficiently
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        N = int(next(iterator))
        M = int(next(iterator))
    except StopIteration:
        return

    # Dictionary to store lower and upper bounds for each row that has constraints
    # L_x: minimum number of black cells in row x
    # U_x: maximum number of black cells in row x
    row_constraints = {}

    for _ in range(M):
        try:
            x = int(next(iterator))
            y = int(next(iterator))
            c = next(iterator)
        except StopIteration:
            break

        if x not in row_constraints:
            row_constraints[x] = {'L': 0, 'U': N}

        if c == 'B':
            # Black cell at (x, y) implies R_x >= y
            row_constraints[x]['L'] = max(row_constraints[x]['L'], y)
        else:
            # White cell at (x, y) implies R_x <= y - 1
            row_constraints[x]['U'] = min(row_constraints[x]['U'], y - 1)

    # Check for immediate contradictions within each row
    for x in row_constraints:
        if row_constraints[x]['L'] > row_constraints[x]['U']:
            print("No")
            return

    # Sort constrained rows in descending order.
    # We process from bottom to top because R_x must be non-increasing (R_x >= R_{x+1}).
    sorted_rows = sorted(row_constraints.keys(), reverse=True)

    # cur_L maintains the minimum valid value for R_x based on constraints from rows below.
    # Since R must be non-increasing, R_x >= max(L_x, R_{x+1}).
    cur_L = 0
    for x in sorted_rows:
        cur_L = max(cur_L, row_constraints[x]['L'])
        # Check if the minimal valid R_x satisfies the upper bound constraint
        if cur_L > row_constraints[x]['U']:
            print("No")
            return

    # If all checks pass, a valid non-increasing sequence exists.
    # Unconstrained rows have L=0, U=N, and since cur_L <= N (guaranteed by checks),
    # they can always be satisfied by setting R_x = cur_L.
    print("Yes")

if __name__ == '__main__':
    solve()

class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)

        def check(L):
            flips = 0
            curr = int(s[0])
            run = 1
            for i in range(1, n):
                val = int(s[i])
                if val == curr:
                    run += 1
                else:
                    curr = val
                    run = 1
                if run > L:
                    flips += 1
                    # Flip current character to break the run
                    curr = 1 - curr
                    run = 1
            return flips <= numOps

        low, high = 1, n
        ans = n
        while low <= high:
            mid = (low + high) // 2
            if check(mid):
                ans = mid
                high = mid - 1
            else:
                low = mid + 1
        return ans

class Solution:
    def subsequencesWithMiddleMode(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        n = len(nums)

        def comb2(x):
            if x < 2:
                return 0
            return x * (x - 1) // 2

        total = 0

        for i in range(2, n - 2):
            m = nums[i]
            L = i
            R = n - 1 - i

            # Compute left_freq and right_freq
            left_freq = {}
            for j in range(i):
                left_freq[nums[j]] = left_freq.get(nums[j], 0) + 1

            right_freq = {}
            for j in range(i + 1, n):
                right_freq[nums[j]] = right_freq.get(nums[j], 0) + 1

            left_non_m = L - left_freq.get(m, 0)
            right_non_m = R - right_freq.get(m, 0)

            # Compute same_pairs for left and right
            left_same_pairs = 0
            for v, cnt in left_freq.items():
                if v != m:
                    left_same_pairs += comb2(cnt)

            right_same_pairs = 0
            for v, cnt in right_freq.items():
                if v != m:
                    right_same_pairs += comb2(cnt)

            # k >= 3 cases
            lf_m = left_freq.get(m, 0)
            rf_m = right_freq.get(m, 0)

            # a=2, b=0
            total += comb2(lf_m) * comb2(right_non_m)
            # a=0, b=2
            total += comb2(left_non_m) * comb2(rf_m)
            # a=1, b=1
            total += lf_m * left_non_m * rf_m * right_non_m
            # a=2, b=1
            total += comb2(lf_m) * rf_m * right_non_m
            # a=1, b=2
            total += lf_m * left_non_m * comb2(rf_m)
            # a=2, b=2
            total += comb2(lf_m) * comb2(rf_m)

            # k = 2 cases
            # a=1, b=0
            if lf_m > 0:
                for v, cnt in left_freq.items():
                    if v != m:
                        # ways to pick 2 distinct non-m from right, neither equal to v
                        ways = comb2(right_non_m) - right_same_pairs - cnt * (right_non_m - cnt)
                        total += lf_m * cnt * ways

            # a=0, b=1
            if rf_m > 0:
                for v, cnt in right_freq.items():
                    if v != m:
                        # ways to pick 2 distinct non-m from left, neither equal to v
                        ways = comb2(left_non_m) - left_same_pairs - cnt * (left_non_m - cnt)
                        total += rf_m * cnt * ways

            total %= MOD

        return total

class Solution:
    def makeStringGood(self, s: str) -> int:
        n = len(s)
        cnt = [0] * 26
        for ch in s:
            cnt[ord(ch) - ord('a')] += 1

        INF = 10**9
        global_best = n  # Cost to delete all characters

        # Iterate over all possible target frequencies k
        for k in range(1, n + 1):
            # Pruning: minimum characters to delete is max(0, n - 26*k)
            if n - 26 * k >= global_best:
                break

            dp = {0: 0}

            for i in range(26):
                c = cnt[i]
                new_dp = {}

                items = sorted(dp.items())
                if not items:
                    break

                max_j = items[-1][0]

                # Compute suffix min of val[j] = dp[j] + j
                # Store as list of (j, min_val) sorted by j ascending
                S_vals = []
                min_v = INF
                for j, cost in reversed(items):
                    min_v = min(min_v, cost + j)
                    S_vals.append((j, min_v))
                S_vals.reverse() 

                # Option 1: final frequency for current char is 0
                # new_dp[j'] = min_{j: j' <= c+j} (dp[j] + c + j)
                # This simplifies to: new_dp[j'] = c + min_{j >= j' - c} (dp[j] + j)
                limit1 = min(n, max_j + c)
                ptr = 0
                len_S = len(S_vals)
                for j_prime in range(limit1 + 1):
                    idx = j_prime - c
                    if idx < 0:
                        idx = 0
                    # Find smallest j in S_vals such that j >= idx
                    while ptr < len_S and S_vals[ptr][0] < idx:
                        ptr += 1
                    if ptr < len_S:
                        cost = S_vals[ptr][1] + c
                        if cost < global_best:
                            if j_prime not in new_dp or cost < new_dp[j_prime]:
                                new_dp[j_prime] = cost
                    else:
                        break

                # Option 2: final frequency for current char is k
                for j, cost in items:
                    avail = c + j
                    if avail >= k:
                        cost2 = avail - k
                        total = cost + cost2
                        if total < global_best:
                            if 0 not in new_dp or total < new_dp[0]:
                                new_dp[0] = total
                            idx2 = avail - k
                            if idx2 <= n:
                                if idx2 not in new_dp or total < new_dp[idx2]:
                                    new_dp[idx2] = total
                    else:
                        cost2 = k - avail
                        total = cost + cost2
                        if total < global_best:
                            if 0 not in new_dp or total < new_dp[0]:
                                new_dp[0] = total

                dp = new_dp
                if not dp:
                    break

            if dp:
                current_min = min(c + j for j, c in dp.items())
                if current_min < global_best:
                    global_best = current_min

        return global_best

from typing import List

class DSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, i):
        root = i
        while self.parent[root] != root:
            root = self.parent[root]
        # Path compression
        while self.parent[i] != root:
            nxt = self.parent[i]
            self.parent[i] = root
            i = nxt
        return root

    def union(self, i, j):
        root_i = self.find(i)
        root_j = self.find(j)
        if root_i != root_j:
            if self.rank[root_i] < self.rank[root_j]:
                root_i, root_j = root_j, root_i
            self.parent[root_j] = root_i
            if self.rank[root_i] == self.rank[root_j]:
                self.rank[root_i] += 1
            return True
        return False

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        present = set(nums)
        # Numbers greater than threshold cannot form any edge
        isolated = sum(1 for x in nums if x > threshold)

        # Map values <= threshold to their original indices
        val_to_idx = {x: i for i, x in enumerate(nums) if x <= threshold}
        dsu = DSU(n)

        # Iterate over each possible common divisor d
        for d in range(1, threshold + 1):
            # Find the first multiple of d present in nums
            first = None
            for j in range(d, threshold + 1, d):
                if j in present:
                    first = j
                    break
            if first is None:
                continue

            # Connect first with other valid multiples of d
            for j in range(d, threshold + 1, d):
                if j == first:
                    continue
                if j in present:
                    # LCM(first, j) = first * j / gcd(first, j)
                    # Since both are multiples of d, gcd(first, j) >= d
                    # So LCM(first, j) <= first * j / d
                    # Condition LCM <= threshold becomes: first <= threshold * d // j
                    if first <= threshold * d // j:
                        dsu.union(val_to_idx[first], val_to_idx[j])
                    else:
                        # As j increases, threshold * d // j decreases.
                        # If the condition fails for current j, it will fail for all larger j.
                        break

        # Count connected components among valid numbers
        components = isolated
        seen_roots = set()
        for x in val_to_idx:
            root = dsu.find(val_to_idx[x])
            if root not in seen_roots:
                seen_roots.add(root)
                components += 1

        return components
